function updateTasks(){const done=tasks.filter(t=>t.done).length;$('progressText').textContent=`${done} / ${tasks.length}`;$('progressFill').style.width=`${done/tasks.length*100}%`;$('tasks').innerHTML=tasks.map(t=>`<div class="task ${t.done?'done':''}"><div class="task-icon">${t.done?'✓':t.icon}</div><div><strong>${t.name}</strong><small>${t.done?'Ready for the festival':'Needs a helping hand'}</small></div>${t.done?'<span class="check">✓</span>':''}</div>`).join('');if(done===3&&!state.done){state.done=true;$('win').classList.add('show');say('Moonfest is ready! Everyone did their part.')}updateAction()}
function updateRoster(){ $('roster').innerHTML=npcs.filter(n=>n.adult).map(n=>`<button class="person ${state.possessed===n.name?'active':''}" data-person="${n.name}"><span class="avatar">${n.emoji}</span><span><strong>${n.name}</strong><small>${n.skill}</small></span><em>${state.possessed===n.name?'IN BODY':'POSSESS'}</em></button>`).join('');document.querySelectorAll('.person').forEach(b=>b.onclick=()=>{const name=b.dataset.person;if(state.possessed===name){release();return}if(!state.possessed){const n=npcs.find(p=>p.name===name);if(Math.hypot(n.x-state.ghost.x,n.y-state.ghost.y)>38){say(`Float closer to ${name} first.`);return}possess(n)}else{release();setTimeout(()=>{const n=npcs.find(p=>p.name===name);if(Math.hypot(n.x-state.ghost.x,n.y-state.ghost.y)>38)say(`Float closer to ${name} first.`);else possess(n)},10)}})}
function nearNPC(){const px=state.possessed?npcs.find(n=>n.name===state.possessed):state.ghost;let found=null,d=Infinity;for(const n of npcs){if(state.possessed===n.name)continue;const nd=Math.hypot(px.x-n.x,px.y-n.y);if(nd<d){d=nd;found=n}}return d<27?found:null}
function updateAction(){const btn=$('taskBtn'),label=$('taskLabel');if(state.possessed){const t=tasks.find(t=>t.who===state.possessed);btn.disabled=!t||t.done||state.done;label.textContent=t?.done?'All done!':state.done?'Moonfest ready':t?'Help with '+t.short:'Interact';$('ghostNote').textContent=`You are borrowing ${state.possessed}'s grown-up skills. Tap their card or press Q to float free.`;return}const n=nearNPC();btn.disabled=false;if(n&&n.adult){const t=tasks.find(t=>t.id===n.task);label.textContent=t?.done?'Visit a friend':'Possess '+n.name}else if(n&&!n.adult){label.textContent='Say hello to Pip'}else label.textContent='Possess an adult helper';$('ghostNote').textContent='You are a harmless house spirit. Help out, make friends, and let everyone enjoy the festival.'}
function possess(n){state.possessed=n.name;state.ghost.x=n.x;state.ghost.y=n.y;updateRoster();updateAction();say(`A gentle shimmer! You are now helping as ${n.name}.`)}
function release(){if(!state.possessed)return;const name=state.possessed;const n=npcs.find(p=>p.name===name);state.possessed=null;state.ghost.x=n.x-14;state.ghost.y=n.y+3;updateRoster();updateAction();say(`You float free. ${name} gives a little wave.`)}
function interact(){if(state.done){$('win').classList.add('show');return}if(state.possessed){const t=tasks.find(a=>a.who===state.possessed);if(t){if(t.done){say(`${state.possessed} already finished that. What a team!`);return}t.done=true;const n=npcs.find(p=>p.name===state.possessed);state.bubbleName=n.name;state.bubbleText='All ready!';state.bubbleUntil=state.time+100;updateTasks();playChime();say(`${state.possessed} ${t.verb.toLowerCase().replace(/^./,c=>c.toUpperCase())} ✓`)}return}const n=nearNPC();if(!n){say('Float close to a grown-up helper, then tap Interact.');return}if(!n.adult){say('Pip is a kid and is staying safely out of the magic. He is happily on cocoa duty!');return}possess(n)}
function move(dx,dy){const p=state.possessed?npcs.find(n=>n.name===state.possessed):state.ghost;if(!p)return;p.x=Math.max(10,Math.min(310,p.x+dx));p.y=Math.max(83,Math.min(164,p.y+dy));state.ghost.x=p.x;state.ghost.y=p.y;updateAction()}
let lastStep=0;const keys={};window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.repeat)return;keys[e.key.toLowerCase()]=true;if(e.key==='ArrowUp'||e.key.toLowerCase()==='w')move(0,-7);if(e.key==='ArrowDown'||e.key.toLowerCase()==='s')move(0,7);if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')move(-7,0);if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')move(7,0);if(e.key.toLowerCase()==='e'||e.key===' ')interact();if(e.key.toLowerCase()==='q')release()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*320,y=(e.clientY-r.top)/r.height*180;let best=null,d=Infinity;for(const n of npcs){const nd=Math.hypot(n.x-x,n.y-y);if(nd<d){d=nd;best=n}}if(best&&d<21){if(state.possessed===best.name)release();else if(Math.hypot(best.x-(state.possessed?npcs.find(n=>n.name===state.possessed).x:state.ghost.x),best.y-(state.possessed?npcs.find(n=>n.name===state.possessed).y:state.ghost.y))<34&&best.adult&&!state.possessed)possess(best);else if(!state.possessed){state.target={x:best.x-16,y:best.y+8};say(`Float near ${best.name}, then interact.`)}else interact()}else{state.target={x:Math.max(10,Math.min(310,x)),y:Math.max(83,Math.min(164,y))}}});
function tickTarget(){if(!state.target)return;const p=state.possessed?npcs.find(n=>n.name===state.possessed):state.ghost;if(!p){state.target=null;return}const dx=state.target.x-p.x,dy=state.target.y-p.y,d=Math.hypot(dx,dy);if(d<4){state.target=null;return}move(dx/d*2,dy/d*2)}
// Add lightweight pointer path-following to mouse/touch taps on the room.
let frame=0;const baseDraw=draw; // wrapped animation hook
function playChime(){if(!state.sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.type='sine';o.frequency.value=660;g.gain.setValueAtTime(.07,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.35);o.start();o.stop(ac.currentTime+.36)}catch(_){}}
$('taskBtn').onclick=interact;$('touchInteract').onclick=interact;$('soundBtn').onclick=()=>{state.sound=!state.sound;$('soundBtn').textContent=state.sound?'♫ Sound on':'♫ Sound off'};$('playAgain').onclick=()=>{tasks.forEach(t=>t.done=false);state.done=false;state.possessed=null;state.ghost={x:158,y:149};state.target=null;$('win').classList.remove('show');updateTasks();updateRoster();say('A quiet little inn awaits its moonfest...')};
document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir,delta={up:[0,-7],down:[0,7],left:[-7,0],right:[7,0]}[dir];let interval;const start=e=>{e.preventDefault();move(...delta);interval=setInterval(()=>move(...delta),115)},stop=()=>clearInterval(interval);b.addEventListener('pointerdown',start);b.addEventListener('pointerup',stop);b.addEventListener('pointerleave',stop);b.addEventListener('pointercancel',stop)});
// Update action range and target movement during rendering frames.
const rawRAF=window.requestAnimationFrame.bind(window);window.requestAnimationFrame=cb=>rawRAF(t=>{if(++frame%3===0){tickTarget();if(state.toastTimer>0){state.toastTimer-=50;if(state.toastTimer<=0)$('toast').style.opacity='0'}if(frame%12===0)updateAction()}cb(t)});
updateTasks();updateRoster();draw();
})();
</script>
</body>
</html>

