function draw(){state.time++;ctx.save();ctx.scale(2,2);room();for(let i=0;i<8;i++)rect(20+(i*43+state.time/45)%290,17+Math.sin(state.time/40+i)*2,1,1,'#fff0b0');const sorted=[...npcs].sort((a,b)=>a.y-b.y);for(const n of sorted)person(n.x,n.y,n.name,n.name===state.possessed);if(!state.possessed)person(state.ghost.x,state.ghost.y,'ghost',true);if(state.possessed){const n=npcs.find(p=>p.name===state.possessed);for(let i=0;i<4;i++){const a=state.time/18+i*1.57;rect(n.x+Math.cos(a)*12,n.y-13+Math.sin(a)*8,2,2,'#ffe78e')}}if(state.bubbleUntil>state.time){const n=npcs.find(p=>p.name===state.bubbleName);if(n){let bx=Math.max(7,Math.min(235,n.x-28));rect(bx,n.y-39,72,17,'#fff6dc');txt(state.bubbleText.slice(0,17),bx+5,n.y-28,5,'#514661')}}ctx.restore();requestAnimationFrame(draw)}
