+rect(426,203,107,38,'#271f35');ctx.fillStyle='#f6aa5d';ctx.beginPath();ctx.moveTo(449,238);ctx.quadraticCurveTo(435,216,460,199);ctx.quadraticCurveTo(457,216,475,208);ctx.quadraticCurveTo(491,194,487,178);ctx.quadraticCurveTo(516,204,505,237);ctx.fill();ctx.fillStyle='#ffdf86';ctx.beginPath();ctx.moveTo(469,236);ctx.quadraticCurveTo(458,218,477,207);ctx.quadraticCurveTo(475,222,491,212);ctx.quadraticCurveTo(496,229,486,238);ctx.fill();rect(354,267,250,13,'#c28764');rect(343,279,273,10,'#684750');
+// hearth cocoa pot and Pip
