+function drawPerson(p){const x=Math.round(p.x),y=Math.round(p.y);ctx.globalAlpha=possessed===p?.28:1;rect(x-14,y+16,28,24,'#553c4c');rect(x-11,y+18,22,20,p.shirt);rect(x-8,y+29,16,11,p.apron);rect(x-10,y+40,7,10,'#4c3847');rect(x+3,y+40,7,10,'#4c3847');rect(x-15,y+23,5,15,p.skin);rect(x+10,y+23,5,15,p.skin);rect(x-11,y+2,22,18,p.skin);rect(x-12,y-2,24,8,p.hair);rect(x-13,y+1,5,13,p.hair);rect(x+8,y+1,5,12,p.hair);rect(x-6,y+9,3,3,'#443142');rect(x+4,y+9,3,3,'#443142');if(p.name==='Mara'){rect(x-12,y+30,24,5,'#fff0d2');rect(x-8,y-8,16,8,'#d9b685');rect(x-5,y-12,10,5,'#fff0d2')}if(p.name==='Oren'){rect(x-8,y+15,16,4,'#65464d');rect(x-10,y+3,20,3,'#553c48')}if(p.name==='Jun'){rect(x-14,y-3,28,5,'#b88055');rect(x-3,y-9,6,6,'#f3d891')}
